import AppKit

/// Polls NSPasteboard.changeCount (macOS has no clipboard-change notification).
final class ClipboardMonitor {
    /// nspasteboard.org markers set by password managers (1Password, Bitwarden, KeePassXC...)
    private static let secret: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
    ]

    private let pb = NSPasteboard.general
    private let store: ClipStore
    private let settings: Settings
    private var last: Int
    private var timer: Timer?
    private let shots = NSMetadataQuery()

    init(store: ClipStore, settings: Settings) {
        self.store = store
        self.settings = settings
        last = pb.changeCount  // don't import whatever was copied before launch
    }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.4, repeats: true) { [weak self] _ in self?.poll() }
        watchScreenshots()
    }

    /// ⌘⇧3/⌘⇧4 only save a file, the pasteboard is never touched. Spotlight flags those files, so copy each new one
    /// to the pasteboard and let poll() record it. ponytail: needs Spotlight indexing on, no folder-watch fallback.
    private func watchScreenshots() {
        shots.predicate = NSPredicate(format: "%K == 1", "kMDItemIsScreenCapture")
        NotificationCenter.default.addObserver(forName: .NSMetadataQueryDidUpdate, object: shots, queue: .main) { [weak self] n in
            guard let self, !settings.paused, settings.recordImages else { return }
            for case let item as NSMetadataItem in n.userInfo?[NSMetadataQueryUpdateAddedItemsKey] as? [Any] ?? [] {
                // fresh files only: a reindex must not replay old screenshots
                guard let path = item.value(forAttribute: NSMetadataItemPathKey) as? String,
                      let made = item.value(forAttribute: NSMetadataItemFSCreationDateKey) as? Date, -made.timeIntervalSinceNow < 60,
                      let img = NSImage(contentsOfFile: path) else { continue }
                pb.clearContents()
                pb.writeObjects([img])
            }
        }
        shots.start()
    }

    private func poll() {
        guard pb.changeCount != last else { return }
        last = pb.changeCount
        guard !settings.paused, last != store.ownChange else { return }
        if settings.ignoreSecrets, !Self.secret.isDisjoint(with: (pb.types ?? []).map(\.rawValue)) { return }

        if settings.recordText, let s = pb.string(forType: .string), !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            store.add(text: s)
        } else if settings.recordImages,
                  let png = pb.data(forType: .png) ?? pb.data(forType: .tiff).flatMap({ NSBitmapImageRep(data: $0)?.representation(using: .png, properties: [:]) }) {
            store.add(png: png)
            saveToFolder(png)
        }
    }

    /// ponytail: saves every recorded image, no dedupe and no screenshot-only filter.
    private func saveToFolder(_ png: Data) {
        guard !settings.saveFolder.isEmpty else { return }
        let f = DateFormatter()
        f.dateFormat = "yyyy-MM-dd 'at' h.mm.ss a"  // same style as macOS: "Screenshot 2026-10-28 at 2.56.24 PM.png"
        let base = "Screenshot \(f.string(from: Date()))"
        let dir = URL(fileURLWithPath: settings.saveFolder)
        // never overwrite: the folder may be the one macOS saves ⌘⇧4 into, with the same name for the same second
        for n in 1...99 {
            let url = dir.appendingPathComponent(n == 1 ? "\(base).png" : "\(base) (\(n)).png")
            if FileManager.default.fileExists(atPath: url.path) { continue }
            do { try png.write(to: url) } catch { NSLog("save image failed: \(error)") }
            return
        }
    }
}
